    // readKeyword reads the given keyword from the input.
    // If the keyword is not present, readKeyword records a syntax error.
    void rec::readKeyword(importReader* r, gocpp::string kw)
    {
        rec::peekByte(gocpp::recv(r), true);
        for(auto i = 0; i < len(kw); i++)
        {
            if(rec::nextByte(gocpp::recv(r), false) != kw[i])
            {
                rec::syntaxError(gocpp::recv(r));
                return;
            }
        }
        if(isIdent(rec::peekByte(gocpp::recv(r), false)))
        {
            rec::syntaxError(gocpp::recv(r));
        }
    }

    // readIdent reads an identifier from the input.
    // If an identifier is not present, readIdent records a syntax error.
    void rec::readIdent(importReader* r)
    {
        auto c = rec::peekByte(gocpp::recv(r), true);
        if(! isIdent(c))
        {
            rec::syntaxError(gocpp::recv(r));
            return;
        }
        for(; isIdent(rec::peekByte(gocpp::recv(r), false)); )
        {
            r->peek = 0;
        }
    }

    // readString reads a quoted string literal from the input.
    // If an identifier is not present, readString records a syntax error.
    void rec::readString(importReader* r)
    {
        //Go switch emulation
        {
            auto condition = rec::nextByte(gocpp::recv(r), true);
            int conditionId = -1;
            if(condition == '`') { conditionId = 0; }
            else if(condition == '"') { conditionId = 1; }
            switch(conditionId)
            {
                case 0:
                    for(; r->err == nullptr; )
                    {
                        if(rec::nextByte(gocpp::recv(r), false) == '`')
                        {
                            break;
                        }
                        if(r->eof)
                        {
                            rec::syntaxError(gocpp::recv(r));
                        }
                    }
                    break;
                case 1:
                    for(; r->err == nullptr; )
                    {
                        auto c = rec::nextByte(gocpp::recv(r), false);
                        if(c == '"')
                        {
                            break;
                        }
                        if(r->eof || c == '\n')
                        {
                            rec::syntaxError(gocpp::recv(r));
                        }
                        if(c == '\\')
                        {
                            rec::nextByte(gocpp::recv(r), false);
                        }
                    }
                    break;
                default:
                    rec::syntaxError(gocpp::recv(r));
                    break;
            }
        }
    }

    // readImport reads an import clause - optional identifier followed by quoted string -
    // from the input.
    void rec::readImport(importReader* r)
    {
        auto c = rec::peekByte(gocpp::recv(r), true);
        if(c == '.')
        {
            r->peek = 0;
        }
        else
        if(isIdent(c))
        {
            rec::readIdent(gocpp::recv(r));
        }
        rec::readString(gocpp::recv(r));
    }

    // readComments is like io.ReadAll, except that it only reads the leading
    // block of comments in the file.
    std::tuple<gocpp::slice<unsigned char>, gocpp::error> readComments(io::Reader f)
    {
        auto r = newImportReader(""_s, f);
        rec::peekByte(gocpp::recv(r), true);
        if(r->err == nullptr && ! r->eof)
        {
            // Didn't reach EOF, so must have found a non-space byte. Remove it.
            r->buf = r->buf.make_slice(0, len(r->buf) - 1);
        }
        return {r->buf, r->err};
    }

    // readGoInfo expects a Go file as input and reads the file up to and including the import section.
    // It records what it learned in *info.
    // If info.fset is non-nil, readGoInfo parses the file and sets info.parsed, info.parseErr,
    // info.imports and info.embeds.
    //
    // It only returns an error if there are problems reading the file,
    // not for syntax errors in the file itself.
    gocpp::error readGoInfo(io::Reader f, fileInfo* info)
    {
        auto r = newImportReader(info->name, f);

        rec::readKeyword(gocpp::recv(r), "package"_s);
        rec::readIdent(gocpp::recv(r));
        for(; rec::peekByte(gocpp::recv(r), true) == 'i'; )
        {
            rec::readKeyword(gocpp::recv(r), "import"_s);
            if(rec::peekByte(gocpp::recv(r), true) == '(')
            {
                rec::nextByte(gocpp::recv(r), false);
                for(; rec::peekByte(gocpp::recv(r), true) != ')' && r->err == nullptr; )
                {
                    rec::readImport(gocpp::recv(r));
                }
                rec::nextByte(gocpp::recv(r), false);
            }
            else
            {
                rec::readImport(gocpp::recv(r));
            }
        }

        info->header = r->buf;

        // If we stopped successfully before EOF, we read a byte that told us we were done.
        // Return all but that last byte, which would cause a syntax error if we let it through.
        if(r->err == nullptr && ! r->eof)
        {
            info->header = r->buf.make_slice(0, len(r->buf) - 1);
        }

        // If we stopped for a syntax error, consume the whole file so that
        // we are sure we don't change the errors that go/parser returns.
        if(r->err == errSyntax)
        {
            r->err = nullptr;
            for(; r->err == nullptr && ! r->eof; )
            {
                rec::readByte(gocpp::recv(r));
            }
            info->header = r->buf;
        }
        if(r->err != nullptr)
        {
            return r->err;
        }

        if(info->fset == nullptr)
        {
            return nullptr;
        }

        // Parse file header & record imports.
        std::tie(info->parsed, info->parseErr) = parser::ParseFile(info->fset, info->name, info->header, parser::ImportsOnly | parser::ParseComments);
        if(info->parseErr != nullptr)
        {
            return nullptr;
        }

        auto hasEmbed = false;
        for(auto [gocpp_ignored, decl] : info->parsed->Decls)
        {
            auto [d, ok] = gocpp::getValue<ast::GenDecl*>(decl);
            if(! ok)
            {
                continue;
            }
            for(auto [gocpp_ignored, dspec] : d->Specs)
            {
                auto [spec, ok] = gocpp::getValue<ast::ImportSpec*>(dspec);
                if(! ok)
                {
                    continue;
                }
                auto quoted = spec->Path->Value;
                auto [path, err] = strconv::Unquote(quoted);
                if(err != nullptr)
                {
                    return mocklib::Errorf("parser returned invalid quoted string: <%s>"_s, quoted);
                }
                if(! isValidImport(path))
                {
                    // The parser used to return a parse error for invalid import paths, but
                    // no longer does, so check for and create the error here instead.
                    info->parseErr = gocpp::Init<scanner::Error>([=](auto& x) {
                        x.Pos = rec::Position(gocpp::recv(info->fset), rec::Pos(gocpp::recv(spec)));
                        x.Msg = "invalid import path: "_s + path;
                    });
                    info->imports = nullptr;
                    return nullptr;
                }
                if(path == "embed"_s)
                {
                    hasEmbed = true;
                }

                auto doc = spec->Doc;
                if(doc == nullptr && len(d->Specs) == 1)
                {
                    doc = d->Doc;
                }
                info->imports = append(info->imports, fileImport {path, rec::Pos(gocpp::recv(spec)), doc});
            }
        }

        // Extract directives.
        for(auto [gocpp_ignored, group] : info->parsed->Comments)
        {
            if(rec::Pos(gocpp::recv(group)) >= info->parsed->Package)
            {
                break;
            }
            for(auto [gocpp_ignored, c] : group->List)
            {
                if(strings::HasPrefix(c->Text, "//go:"_s))
                {
                    info->directives = append(info->directives, Directive {c->Text, rec::Position(gocpp::recv(info->fset), c->Slash)});
                }
            }
        }

        // If the file imports "embed",
        // we have to look for //go:embed comments
        // in the remainder of the file.
        // The compiler will enforce the mapping of comments to
        // declared variables. We just need to know the patterns.
        // If there were //go:embed comments earlier in the file
        // (near the package statement or imports), the compiler
        // will reject them. They can be (and have already been) ignored.
        if(hasEmbed)
        {
            gocpp::slice<unsigned char> line = {};
            for(auto first = true; rec::findEmbed(gocpp::recv(r), first); first = false)
            {
                line = line.make_slice(0, 0);
                auto pos = r->pos;
                for(; ; )
                {
                    auto c = rec::readByteNoBuf(gocpp::recv(r));
                    if(c == '\n' || r->err != nullptr || r->eof)
                    {
                        break;
                    }
                    line = append(line, c);
                }
                // Add args if line is well-formed.
                // Ignore badly-formed lines - the compiler will report them when it finds them,
                // and we can pretend they are not there to help go list succeed with what it knows.
                auto [embs, err] = parseGoEmbed(gocpp::string(line), pos);
                if(err == nullptr)
                {
                    info->embeds = append(info->embeds, embs);
                }
            }
        }

        return nullptr;
    }

    // isValidImport checks if the import is a valid import using the more strict
    // checks allowed by the implementation restriction in https://go.dev/ref/spec#Import_declarations.
    // It was ported from the function of the same name that was removed from the
    // parser in CL 424855, when the parser stopped doing these checks.
    bool isValidImport(gocpp::string s)
    {
        auto illegalChars = "!\"#$%&'()*,:;<=>?[\\]^{|}"_s + "`\uFFFD"_s;
        for(auto [gocpp_ignored, r] : s)
        {
            if(! unicode::IsGraphic(r) || unicode::IsSpace(r) || strings::ContainsRune(illegalChars, r))
            {
                return false;
            }
        }
        return s != ""_s;
    }

